/* Tech Robòtica · unitat 7 «Missions» */
Object.assign(TBADGE, {
  k_neteja: { id: 'k_neteja', ico: '🧹', n: 'Enginyer/a de la neteja|Ingeniero/a de la limpieza', d: "Has programat un robot aspirador amb una estratègia: rebotar o fer zig-zag amb una variable que recorda el costat.|Has programado un robot aspirador con una estrategia: rebotar o hacer zigzag con una variable que recuerda el lado." },
  k_sumo: { id: 'k_sumo', ico: '🥇', n: 'Campió/ona del dohyo|Campeón/a del dohyo', d: "El teu robot de sumo no surt mai del dohyo, busca el rival amb els ultrasons i l'empeny fora.|Tu robot de sumo no sale nunca del dohyo, busca al rival con los ultrasonidos y lo empuja fuera." },
  k_rescat: { id: 'k_rescat', ico: '🛟', n: 'Equip de rescat|Equipo de rescate', d: "Has dividit una missió en fases: buscar, apuntar, empènyer fins a la base i avisar.|Has dividido una misión en fases: buscar, apuntar, empujar hasta la base y avisar." },
  k_cursa: { id: 'k_cursa', ico: '⏱️', n: 'Pilot/a contrarellotge|Piloto contrarreloj', d: "El teu robot fa la volta al circuit, passa per tots els punts de control i s'atura a la meta abans que s'acabi el temps.|Tu robot da la vuelta al circuito, pasa por todos los puntos de control y se para en la meta antes de que se acabe el tiempo." }
});
ROBOTICA_UNITS[7] = (() => {
  /* ---------- pistes i programes que es fan servir en diversos passos ---------- */
  const f1 = v => +v.toFixed(1);
  // circuit en forma de rectangle amb les cantonades arrodonides (la cinta negra)
  const rrect = (x0, y0, x1, y1, r, n) => { const p = [], c = [[x1 - r, y0 + r, -90], [x1 - r, y1 - r, 0], [x0 + r, y1 - r, 90], [x0 + r, y0 + r, 180]];
    for (const [cx, cy, a0] of c) for (let i = 0; i <= n; i++) { const a = (a0 + 90 * i / n) * Math.PI / 180; p.push([f1(cx + r * Math.cos(a)), f1(cy + r * Math.sin(a))]); } return p; };
  // el circuit del port (projecte): dues corbes grans i una xicana a la recta de baix
  const PORT = (() => { const p = [];
    for (let x = 30; x < 110; x += 20) p.push([x, 12]);
    for (let i = 0; i <= 10; i++) { const a = (-90 + 18 * i) * Math.PI / 180; p.push([f1(110 + 28 * Math.cos(a)), f1(40 + 28 * Math.sin(a))]); }
    for (let i = 1; i < 16; i++) { const x = 110 - 80 * i / 16, b = x > 50 && x < 90 ? 14 * (1 + Math.cos((x - 70) / 20 * Math.PI)) / 2 : 0; p.push([f1(x), f1(68 - b)]); }
    for (let i = 0; i <= 10; i++) { const a = (90 + 18 * i) * Math.PI / 180; p.push([f1(30 + 28 * Math.cos(a)), f1(40 + 28 * Math.sin(a))]); }
    return p.map(([x, y]) => [f1(x + 5), f1(y + 2)]); })();
  // circuit A (el moll) i circuit B (la drassana), cadascun amb la seva ratlla de meta i els seus punts de control
  const CA = { lines: [{ p: rrect(9, 14, 131, 66, 26, 8), closed: true, w: 2 }, { p: [[40, 9], [40, 19]], w: 2 }], bot: [48, 14, 90], zones: [{ id: 'meta', r: [24, 4, 22, 20], col: 'yellow', label: 'META|META' }] };
  const CA_CP = [[105, 14], [131, 40], [70, 66], [9, 40], [35, 14]];
  const CB = { lines: [{ p: rrect(10, 10, 130, 70, 16, 6), closed: true, w: 2 }, { p: [[40, 5], [40, 15]], w: 2 }], bot: [48, 10, 90], zones: [{ id: 'meta', r: [24, 0, 22, 20], col: 'yellow', label: 'META|META' }] };
  const CB_CP = [[110, 10], [130, 40], [70, 70], [10, 40], [30, 10]];
  const CP_PORT = { lines: [{ p: PORT, closed: true, w: 2 }, { p: [[47, 9], [47, 19]], w: 2 }], bot: [55, 14, 90], zones: [{ id: 'meta', r: [31, 4, 22, 20], col: 'yellow', label: 'META|META' }] };
  const PORT_CP = [[115, 14], [143, 42], [75, 56], [7, 42], [35, 14]];
  // seguidor de línia amb dos sensors que s'atura a la ratlla de meta (L i R a la vegada sobre negre)
  const CURSA = (s, lo, hi) => `start{ until:L=1&&R=1{ if:L=1{ run:L,fwd,${lo} run:R,fwd,${hi} } else{ if:R=1{ run:L,fwd,${hi} run:R,fwd,${lo} } else{ run:all,fwd,${s} } } } stop:all }`;
  // aspirador: rebotar (girar uns 130° quan veu la paret) i fer zig-zag (la variable d recorda cap a quin costat toca girar)
  const REBOT = (t, s) => `forever{ if:dist<10{ run:L,fwd,100 run:R,back,100 wait:${t} } else{ run:all,fwd,${s} } }`;
  const ZIGZAG = (pre = '') => `start{ ${pre}set:d,0 } forever{ if:dist<8{ if:$d=0{ run:L,fwd,100 run:R,back,100 wait:590 run:all,fwd,150 wait:450 run:L,fwd,100 run:R,back,100 wait:590 set:d,1 } else{ run:L,back,100 run:R,fwd,100 wait:590 run:all,fwd,150 wait:450 run:L,back,100 run:R,fwd,100 wait:590 set:d,0 } } else{ run:all,fwd,200 } }`;
  // sumo: primer la vora (sensors de línia), després el rival (ultrasons), i si no veu res, gira per buscar
  const SUMO = 'forever{ if:L=1||R=1{ run:all,back,150 wait:200 run:L,fwd,100 run:R,back,100 wait:200 } else{ if:dist<60{ run:all,fwd,255 } else{ run:L,fwd,90 run:R,back,90 } } }';
  const RING = { x: 50, y: 45, r: 38 }, DOHYO = { w: 100, h: 90, ring: RING, border: false };
  const can = (x, y) => ({ x, y, r: 3, kind: 'can' }), ninot = (x, y) => ({ x, y, r: 4, kind: 'box' });
  // rescat: la cova (el robot al mig) amb la balisa i la base en la mateixa direcció
  const at = (a, r) => [f1(50 + r * Math.sin(a * Math.PI / 180)), f1(40 - r * Math.cos(a * Math.PI / 180))];
  const COVA = a => ({ objs: [{ x: at(a, 20)[0], y: at(a, 20)[1], r: 3, kind: 'ball' }], zones: [{ id: 'base', c: [...at(a, 33), 11], col: 'blue', label: 'BASE|BASE' }] });
  const BUSCA = (sc, end = '') => `start{ run:L,fwd,${sc} run:R,back,${sc} until:dist<25{ wait:10 } run:all,fwd,120 until:aM>200{ wait:10 } wait:300 stop:all ${end}}`;
  const BASE = x => ({ zones: [{ id: 'base', r: [x, 12, 22, 26], col: 'blue', label: 'BASE|BASE' }] });
  const has = (P, k) => { let f = false; const w = l => (l || []).forEach(b => { if (b.k === k) f = true; w(b.b); w(b.e); }); Object.values(P).forEach(w); return f; };

  return { t: 'Missions|Misiones', d: 'Aspirar, sumo, rescat i contrarellotge|Aspirar, sumo, rescate y contrarreloj', color: '#E2574C', s: [
  /* ---------- Sessió 1 · El robot aspirador ---------- */
  { id: 'k7-1', t: 'El robot aspirador|El robot aspirador', min: 45, badge: 'k_neteja',
    learn: ["Una missió combina sensors, decisions i una estratègia, i es prova a diverses pistes.|Una misión combina sensores, decisiones y una estrategia, y se prueba en varias pistas.",
      "Un aspirador que rebota cobreix el terra a l'atzar; fent zig-zag el cobreix amb ordre i més de pressa.|Un aspirador que rebota cubre el suelo al azar; haciendo zigzag lo cubre con orden y más deprisa.",
      "Una variable pot recordar una decisió, com ara cap a quin costat toca girar la propera vegada.|Una variable puede recordar una decisión, como hacia qué lado toca girar la próxima vez."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'A la unitat anterior vas fer servir <b>variables</b>. Per a què serveix una variable?|En la unidad anterior usaste <b>variables</b>. ¿Para qué sirve una variable?',
        opts: ['Per guardar un número que el programa pot consultar i canviar|Para guardar un número que el programa puede consultar y cambiar', 'Per fer que els motors vagin més de pressa|Para hacer que los motores vayan más deprisa', 'Per encendre els llums del cotxe|Para encender las luces del coche'], a: 0,
        ex: "Una variable és com una capsa amb nom on el robot guarda un número: una velocitat, un comptador…|Una variable es como una caja con nombre donde el robot guarda un número: una velocidad, un contador…" },
      { k: 'quiz', ph: 'recorda', q: "Si el sensor d'ultrasons <b>no veu res</b> al davant, quin número dona?|Si el sensor de ultrasonidos <b>no ve nada</b> delante, ¿qué número da?",
        opts: ['500|500', '0|0', '255|255'], a: 0, ex: "Mesura de 2 a 400 cm; si no li torna l'eco, la llibreria del Maqueen dona 500.|Mide de 2 a 400 cm; si no le vuelve el eco, la librería del Maqueen da 500." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'poble', title: 'La Setmana de les Missions|La Semana de las Misiones',
        t: "Arriba la <b>Setmana de les Missions</b> de l'illa! Cada dia, una missió de veritat: netejar, una competició de sumo, un rescat i una cursa contrarellotge. Avui, l'hostal de la plaça ens demana un <b>robot aspirador</b> que netegi el menjador de nit, quan no hi ha ningú. Per fer-ho necessitaràs tot el que has après: motors, girs, ultrasons… i variables!|¡Llega la <b>Semana de las Misiones</b> de la isla! Cada día, una misión de verdad: limpiar, una competición de sumo, un rescate y una carrera contrarreloj. Hoy, el hostal de la plaza nos pide un <b>robot aspirador</b> que limpie el comedor de noche, cuando no hay nadie. Para hacerlo necesitarás todo lo que has aprendido: motores, giros, ultrasonidos… ¡y variables!" },
      { k: 'story', ph: 'missio', who: 'numi',
        t: "Una missió no és un sol repte: és un problema gran amb diverses pistes. Així ho fan els enginyers i enginyeres de robots:|Una misión no es un solo reto: es un problema grande con varias pistas. Así lo hacen los ingenieros e ingenieras de robots:",
        box: "<ol><li><b>Entén la missió</b>: què vol dir «ho he aconseguit»?</li><li><b>Tria els sensors</b> que t'ajuden.</li><li><b>Pensa una estratègia</b> i escriu-la en blocs.</li><li><b>Prova-la a totes les pistes</b> i millora-la.</li></ol>|<ol><li><b>Entiende la misión</b>: ¿qué quiere decir «lo he conseguido»?</li><li><b>Elige los sensores</b> que te ayudan.</li><li><b>Piensa una estrategia</b> y escríbela en bloques.</li><li><b>Pruébala en todas las pistas</b> y mejórala.</li></ol>" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Aspirador|Aspirador', t: 'Com neteja un robot aspirador?|¿Cómo limpia un robot aspirador?', anim: 'k7cover',
          x: "Un robot aspirador senzill <b>no té cap mapa</b> de la casa: només nota les parets i els mobles amb els sensors. Per netejar-ho tot, segueix una <span class='hl'>estratègia</span>: unes regles que repeteix fins que s'acaba la bateria. Les més conegudes són <b>rebotar</b> i fer <b>zig-zag</b>.|Un robot aspirador sencillo <b>no tiene ningún mapa</b> de la casa: solo nota las paredes y los muebles con los sensores. Para limpiarlo todo, sigue una <span class='hl'>estrategia</span>: unas reglas que repite hasta que se acaba la batería. Las más conocidas son <b>rebotar</b> y hacer <b>zigzag</b>.",
          tip: "Alguns aspiradors moderns sí que fan un mapa amb altres sensors, però tots comencen per regles com aquestes.|Algunos aspiradores modernos sí hacen un mapa con otros sensores, pero todos empiezan por reglas como estas." },
        { k: 'Mesurar|Medir', t: 'Quant ha netejat?|¿Cuánto ha limpiado?', anim: 'k7grid',
          x: "Per saber si ho ha fet bé, imaginem el terra dividit en <b>quadrets de 5 × 5 cm</b>. Un quadret queda net quan el centre del robot hi passa per sobre. El <span class='hl'>percentatge</span> és quants quadrets nets hi ha de cada 100. Un 50 % vol dir que ha netejat la meitat del terra.|Para saber si lo ha hecho bien, imaginamos el suelo dividido en <b>cuadraditos de 5 × 5 cm</b>. Un cuadradito queda limpio cuando el centro del robot pasa por encima. El <span class='hl'>porcentaje</span> es cuántos cuadraditos limpios hay de cada 100. Un 50 % quiere decir que ha limpiado la mitad del suelo.",
          tip: "Passar dues vegades pel mateix lloc no compta doble: el quadret ja era net.|Pasar dos veces por el mismo sitio no cuenta doble: el cuadradito ya estaba limpio." },
        { k: 'Estratègia 1|Estrategia 1', t: 'Rebotar|Rebotar',
          robo: { w: { w: 100, h: 60, bot: [15, 30, 90], time: 30 }, prog: REBOT(800, 200) },
          x: "La regla més senzilla: <b>endavant</b> fins que els ultrasons veuen la paret a menys de 10 cm; llavors <b>gira</b> una bona estona (uns 120°) i torna a anar endavant. Com que cada rebot l'envia en una direcció diferent, a poc a poc va passant per tot arreu… però també repeteix molts llocs.|La regla más sencilla: <b>adelante</b> hasta que los ultrasonidos ven la pared a menos de 10 cm; entonces <b>gira</b> un buen rato (unos 120°) y vuelve a ir adelante. Como cada rebote lo envía en una dirección diferente, poco a poco va pasando por todas partes… pero también repite muchos sitios." },
        { k: 'Estratègia 2|Estrategia 2', t: 'Zig-zag amb memòria|Zigzag con memoria',
          robo: { w: { w: 100, h: 60, bot: [10, 8, 90], time: 45 }, prog: ZIGZAG(), varNames: { d: 'costat|lado' } },
          x: "Com quan es talla la gespa: va fins a la paret, fa mitja volta <b>baixant un carril</b> i torna. Però el gir ha de ser una vegada a la dreta i la següent a l'esquerra! El robot ho recorda amb una <span class='hl'>variable</span>, <b>costat</b>: si val 0, gira a la dreta i la posa a 1; si val 1, gira a l'esquerra i la torna a 0.|Como cuando se corta el césped: va hasta la pared, da media vuelta <b>bajando un carril</b> y vuelve. ¡Pero el giro tiene que ser una vez a la derecha y la siguiente a la izquierda! El robot lo recuerda con una <span class='hl'>variable</span>, <b>lado</b>: si vale 0, gira a la derecha y la pone a 1; si vale 1, gira a la izquierda y la vuelve a 0.",
          tip: "En 45 segons, el zig-zag neteja més del 60 % del menjador sense tocar cap paret; rebotant, al voltant del 40 %.|En 45 segundos, el zigzag limpia más del 60 % del comedor sin tocar ninguna pared; rebotando, alrededor del 40 %." },
        { k: 'Compte!|¡Cuidado!', t: 'Mitja volta exacta: sempre pel mateix camí|Media vuelta exacta: siempre por el mismo camino',
          robo: { w: { w: 100, h: 60, bot: [15, 30, 90], time: 20 }, prog: REBOT(1180, 150) },
          x: "Si quan veu la paret gira <b>exactament 180°</b> (1180 ms), el robot torna enrere per la mateixa línia… i va i ve sempre pel mateix lloc. La resta del menjador queda bruta!|Si cuando ve la pared gira <b>exactamente 180°</b> (1180 ms), el robot vuelve atrás por la misma línea… y va y viene siempre por el mismo sitio. ¡El resto del comedor queda sucio!",
          bad: "Com més gira, millor neteja.|Cuanto más gira, mejor limpia.", good: "Un gir que no sigui de 180° fa que cada rebot vagi cap a un lloc nou.|Un giro que no sea de 180° hace que cada rebote vaya hacia un sitio nuevo." }
      ] },
      { k: 'seq', ph: 'mans', q: "Ordena el que fa l'aspirador <b>zig-zag</b> cada vegada que arriba a una paret (quan la variable costat val 0).|Ordena lo que hace el aspirador <b>zigzag</b> cada vez que llega a una pared (cuando la variable lado vale 0).",
        items: ['Els ultrasons veuen la paret a menys de 8 cm|Los ultrasonidos ven la pared a menos de 8 cm', 'Gira 90° a la dreta|Gira 90° a la derecha', 'Avança un tros curt: baixa un carril|Avanza un trozo corto: baja un carril', 'Gira 90° més a la dreta: ja mira cap a l\'altre costat|Gira 90° más a la derecha: ya mira hacia el otro lado', 'Posa costat a 1: la propera vegada girarà a l\'esquerra|Pone lado a 1: la próxima vez girará a la izquierda'],
        ex: "Dos girs de 90° cap al mateix costat fan mitja volta, però amb un carril de diferència. I la variable recorda que la propera vegada toca l'altre costat.|Dos giros de 90° hacia el mismo lado hacen media vuelta, pero con un carril de diferencia. Y la variable recuerda que la próxima vez toca el otro lado." },
      { k: 'unplug', ph: 'mans', ico: '🧹', title: "L'aspirador de llapis|El aspirador de lápiz",
        t: "Amb un full quadriculat, un llapis i algú de casa. Dibuixeu un menjador de 12 × 8 quadrets amb una taula de 2 × 2 al mig.|Con una hoja cuadriculada, un lápiz y alguien de casa. Dibujad un comedor de 12 × 8 cuadraditos con una mesa de 2 × 2 en el medio.",
        steps: ["Primer, <b>rebotar</b>: comença en una cantonada i avança en diagonal; quan toquis una paret, canvia de direcció com una pilota. Pinta cada quadret per on passis.|Primero, <b>rebotar</b>: empieza en una esquina y avanza en diagonal; cuando toques una pared, cambia de dirección como una pelota. Pinta cada cuadradito por donde pases.",
          "Para quan hagis fet 40 passos i compta els quadrets pintats.|Para cuando hayas dado 40 pasos y cuenta los cuadraditos pintados.",
          "En un altre full, <b>zig-zag</b>: fila per fila, d'una paret a l'altra, baixant una fila a cada gir. Torna a parar als 40 passos.|En otra hoja, <b>zigzag</b>: fila por fila, de una pared a la otra, bajando una fila en cada giro. Vuelve a parar a los 40 pasos.",
          "Quin full té més quadrets nets? Calculeu el percentatge: quadrets nets ÷ quadrets del terra × 100.|¿Qué hoja tiene más cuadraditos limpios? Calculad el porcentaje: cuadraditos limpios ÷ cuadraditos del suelo × 100."],
        tip: "Fixa't en els racons i al voltant de la taula: és on costa més arribar.|Fíjate en los rincones y alrededor de la mesa: es donde cuesta más llegar." },
      { k: 'rpredict', ph: 'prova', q: "Aquest programa fa <b>dues vegades</b>: avança fins a 10 cm de la paret i gira 90° a la dreta. <b>On acabarà</b> el robot?|Este programa hace <b>dos veces</b>: avanza hasta 10 cm de la pared y gira 90° a la derecha. <b>¿Dónde terminará</b> el robot?",
        w: { w: 100, h: 60, bot: [15, 30, 90], marks: { A: [87, 47], B: [87, 13], C: [15, 47] } }, scripts: ['start'],
        prog: 'start{ rep:2{ run:all,fwd,150 until:dist<10{ wait:10 } run:L,fwd,100 run:R,back,100 wait:590 } stop:all }', a: 'A',
        ex: "Primer va fins a la paret de la dreta i gira cap avall; després baixa fins a la paret de baix i torna a girar. Acaba a la cantonada de baix a la dreta, mirant cap a l'esquerra.|Primero va hasta la pared de la derecha y gira hacia abajo; después baja hasta la pared de abajo y vuelve a girar. Termina en la esquina de abajo a la derecha, mirando hacia la izquierda." },
      { k: 'rspot', ph: 'investiga', q: "Aquest és l'aspirador zig-zag. <b>Toca el bloc que fa que, a la paret següent, giri cap a l'altre costat.</b>|Este es el aspirador zigzag. <b>Toca el bloque que hace que, en la pared siguiente, gire hacia el otro lado.</b>",
        w: { w: 100, h: 60, bot: [10, 8, 90], time: 45 }, vars: ['d'], varNames: { d: 'costat|lado' },
        prog: 'start{ set:d,0 } forever{ if:dist<8{ if:$d=0{ run:L,fwd,100 run:R,back,100 wait:590 run:all,fwd,150 wait:450 run:L,fwd,100 run:R,back,100 wait:590 set:d,1! } else{ run:L,back,100 run:R,fwd,100 wait:590 run:all,fwd,150 wait:450 run:L,back,100 run:R,fwd,100 wait:590 set:d,0 } } else{ run:all,fwd,200 } }',
        yes: "Exacte! Posar costat a 1 és com fer-se un nus al dit: la propera vegada, el «si» triarà l'altra branca.|¡Exacto! Poner lado a 1 es como hacerse un nudo en el dedo: la próxima vez, el «si» elegirá la otra rama.",
        ex: "És «posa costat a 1»: canvia la variable perquè, a la paret següent, el «si costat = 0» sigui fals i el robot giri a l'esquerra.|Es «pon lado a 1»: cambia la variable para que, en la pared siguiente, el «si lado = 0» sea falso y el robot gire a la izquierda." },
      { k: 'move', ph: 'pausa', secs: 40, t: "Fes d'aspirador zig-zag al lloc! Camina 4 passos endavant (al lloc), gira a la dreta, un passet, gira a la dreta. Ara 4 passos més, gira a l'<b>esquerra</b>, un passet, gira a l'esquerra. Recordes cap a on toca girar? Repeteix-ho tres vegades sense equivocar-te de costat!|¡Haz de aspirador zigzag en el sitio! Camina 4 pasos adelante (en el sitio), gira a la derecha, un pasito, gira a la derecha. Ahora 4 pasos más, gira a la <b>izquierda</b>, un pasito, gira a la izquierda. ¿Recuerdas hacia dónde toca girar? ¡Repítelo tres veces sin equivocarte de lado!" },
      { k: 'robo', ph: 'repte', q: "<b>Primer aspirador.</b> Aquest robot només va endavant i es queda encallat a la paret. Fes que <b>reboti</b>: si veu la paret a menys de 10 cm, que giri una bona estona; si no, endavant. Ha de netejar el <b>20 %</b> del menjador en 30 segons.|<b>Primer aspirador.</b> Este robot solo va adelante y se queda atascado en la pared. Haz que <b>rebote</b>: si ve la pared a menos de 10 cm, que gire un buen rato; si no, adelante. Tiene que limpiar el <b>20 %</b> del comedor en 30 segundos.",
        w: { w: 100, h: 60, bot: [15, 30, 90], goal: [{ k: 'cover', min: .2 }], time: 30 },
        pal: ['run', 'stop', 'wait', 'if', 'else'], ops: ['dist'], scripts: ['forever'],
        prog: 'forever{ run:all,fwd,150 }', sol: REBOT(800, 150),
        hint: "Dins de «per sempre», posa un «si distància < 10» amb «si no». Al «si»: motor esquerre endavant, dret enrere i espera uns 800 ms. Al «si no»: els dos endavant.|Dentro de «para siempre», pon un «si distancia < 10» con «si no». En el «si»: motor izquierdo adelante, derecho atrás y espera unos 800 ms. En el «si no»: los dos adelante." },
      { k: 'robo', ph: 'repte', q: "Al menjador hi ha <b>mobles</b>, i cada nit els canvien de lloc! El mateix programa ha de netejar el <b>20 %</b> a les tres pistes en 45 segons. Un programa amb temps fixos no servirà: cal fer servir els ultrasons.|En el comedor hay <b>muebles</b>, ¡y cada noche los cambian de sitio! El mismo programa tiene que limpiar el <b>20 %</b> en las tres pistas en 45 segundos. Un programa con tiempos fijos no servirá: hay que usar los ultrasonidos.",
        w: { w: 110, h: 70, bot: [15, 35, 90], walls: [[45, 25, 18, 18]], goal: [{ k: 'cover', min: .2 }], time: 45, alts: [{ walls: [[70, 10, 14, 26]] }, { walls: [[35, 44, 26, 12], [80, 12, 12, 12]] }] },
        pal: ['run', 'stop', 'wait', 'if', 'else'], ops: ['dist'], scripts: ['forever'],
        sol: REBOT(800, 200),
        hint: "Els ultrasons també veuen els mobles: la regla de rebotar funciona igual. Si no hi arriba, prova d'anar més de pressa (200) o de canviar el temps del gir (entre 600 i 1000 ms).|Los ultrasonidos también ven los muebles: la regla de rebotar funciona igual. Si no llega, prueba a ir más deprisa (200) o a cambiar el tiempo del giro (entre 600 y 1000 ms)." },
      { k: 'robo', ph: 'repte', q: "<b>Zig-zag amb memòria.</b> L'amo de l'hostal vol el <b>58 %</b> net en 45 segons i <b>sense tocar les parets</b>, i rebotant no s'hi arriba. El programa ja gira bé a la dreta i posa <b>costat</b> a 1, però a la branca «si no» no hi ha res. Completa-la perquè giri a l'<b>esquerra</b> i torni a posar costat a 0.|<b>Zigzag con memoria.</b> El dueño del hostal quiere el <b>58 %</b> limpio en 45 segundos y <b>sin tocar las paredes</b>, y rebotando no se llega. El programa ya gira bien a la derecha y pone <b>lado</b> a 1, pero en la rama «si no» no hay nada. Complétala para que gire a la <b>izquierda</b> y vuelva a poner lado a 0.",
        w: { w: 100, h: 60, bot: [10, 8, 90], goal: [{ k: 'cover', min: .58 }, { k: 'nohit' }], time: 45 },
        pal: ['run', 'stop', 'wait', 'if', 'else', 'set'], ops: ['dist'], scripts: ['start', 'forever'], vars: ['d'], varNames: { d: 'costat|lado' },
        prog: 'start{ set:d,0 } forever{ if:dist<8{ if:$d=0{ run:L,fwd,100 run:R,back,100 wait:590 run:all,fwd,150 wait:450 run:L,fwd,100 run:R,back,100 wait:590 set:d,1 } else{ } } else{ run:all,fwd,200 } }',
        sol: ZIGZAG(),
        hint: "Copia la branca de dalt però a l'inrevés: per girar a l'esquerra, motor esquerre <b>enrere</b> i dret <b>endavant</b> (590 ms). Al final, posa costat a 0.|Copia la rama de arriba pero al revés: para girar a la izquierda, motor izquierdo <b>atrás</b> y derecho <b>adelante</b> (590 ms). Al final, pon lado a 0." },
      { k: 'rcreate', ph: 'crea', name: "L'aspirador de l'hostal|El aspirador del hostal",
        q: "<b>Crea el teu aspirador!</b> L'hostal té dues sales amb un sofà en llocs diferents. Tria l'estratègia (rebotar, zig-zag o una d'inventada) i fes que, mentre neteja, porti els <b>llums de sota</b> encesos, com els aspiradors de veritat.|<b>¡Crea tu aspirador!</b> El hostal tiene dos salas con un sofá en sitios diferentes. Elige la estrategia (rebotar, zigzag o una inventada) y haz que, mientras limpia, lleve las <b>luces de abajo</b> encendidas, como los aspiradores de verdad.",
        crit: ['Neteja almenys el 40 % de les dues sales en 50 segons|Limpia al menos el 40 % de las dos salas en 50 segundos', 'Porta els llums de sota encesos|Lleva las luces de abajo encendidas', 'La teva estratègia: tu tries els girs i les velocitats|Tu estrategia: tú eliges los giros y las velocidades'],
        w: { w: 110, h: 70, bot: [10, 8, 90], walls: [[0, 50, 30, 20]], goal: [{ k: 'cover', min: .4 }], time: 50, alts: [{ walls: [[80, 0, 30, 18]] }] },
        pal: ['run', 'stop', 'wait', 'if', 'else', 'set', 'under', 'car'], ops: ['dist'], scripts: ['start', 'forever'], vars: ['d'], varNames: { d: 'costat|lado' },
        sol: ZIGZAG('under:all,blue '),
        check(P) { return has(P, 'under') ? null : "Neteja, però li falten els llums de sota! Posa un bloc «llums de sota» a «en iniciar».|¡Limpia, pero le faltan las luces de abajo! Pon un bloque «luces de abajo» en «al iniciar»."; } },
      { k: 'quiz', ph: 'tanca', q: 'Per què el zig-zag necessita una <b>variable</b>?|¿Por qué el zigzag necesita una <b>variable</b>?',
        opts: ["Per recordar cap a quin costat ha de girar a la paret següent|Para recordar hacia qué lado tiene que girar en la pared siguiente", 'Per mesurar la distància a la paret|Para medir la distancia a la pared', 'Per anar més de pressa|Para ir más deprisa'], a: 0,
        ex: "Les dues parets semblen iguals per als ultrasons: només la variable sap si la darrera vegada va girar a la dreta o a l'esquerra.|Las dos paredes parecen iguales para los ultrasonidos: solo la variable sabe si la última vez giró a la derecha o a la izquierda." },
      { k: 'quiz', ph: 'tanca', q: "Un aspirador ha netejat <b>120</b> quadrets d'un terra de <b>240</b>. Quin percentatge ha netejat?|Un aspirador ha limpiado <b>120</b> cuadraditos de un suelo de <b>240</b>. ¿Qué porcentaje ha limpiado?",
        opts: ['El 50 %|El 50 %', 'El 120 %|El 120 %', 'El 24 %|El 24 %'], a: 0, ex: "120 és la meitat de 240: la meitat és el 50 %.|120 es la mitad de 240: la mitad es el 50 %." },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 2 · Sumo ---------- */
  { id: 'k7-2', t: 'Sumo|Sumo', min: 45, badge: 'k_sumo',
    learn: ["En el sumo de robots, qui surt del dohyo perd: els sensors de línia veuen la vora negra (i l'aire de fora) i el robot retrocedeix.|En el sumo de robots, quien sale del dohyo pierde: los sensores de línea ven el borde negro (y el aire de fuera) y el robot retrocede.",
      "Els ultrasons busquen el rival: si no veu res, el robot gira sobre si mateix; si el veu, ataca a tota velocitat.|Los ultrasonidos buscan al rival: si no ve nada, el robot gira sobre sí mismo; si lo ve, ataca a toda velocidad.",
      "L'ordre dels «si» és la prioritat: primer la seguretat (la vora), després l'atac i, al final, buscar.|El orden de los «si» es la prioridad: primero la seguridad (el borde), después el ataque y, al final, buscar."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Quina estratègia d'aspirador netejava més terra en el mateix temps?|¿Qué estrategia de aspirador limpiaba más suelo en el mismo tiempo?",
        opts: ['El zig-zag, fila per fila|El zigzag, fila por fila', 'Rebotar a l\'atzar|Rebotar al azar', 'Girar sempre 180°|Girar siempre 180°'], a: 0 },
      { k: 'quiz', ph: 'recorda', q: "Què val un sensor de línia quan és sobre la <b>cinta negra</b> o <b>fora de la taula</b>?|¿Qué vale un sensor de línea cuando está sobre la <b>cinta negra</b> o <b>fuera de la mesa</b>?",
        opts: ['1|1', '0|0', '500|500'], a: 0, ex: "El sensor envia llum cap avall: el negre no la torna, i a l'aire tampoc no rebota. En tots dos casos dona 1.|El sensor envía luz hacia abajo: el negro no la devuelve, y en el aire tampoco rebota. En los dos casos da 1." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'taller', title: 'La competició de sumo|La competición de sumo',
        t: "Avui el taller s'omple de gent: és la <b>competició de sumo de robots</b>! Dos robots entren en un cercle, el <b>dohyo</b>, i cadascun intenta treure l'altre fora empenyent-lo. Qui surt del cercle, perd. Abans de la competició, entrenarem amb llaunes i amb el <b>ninot d'entrenament</b>, una caixa que fa de rival.|Hoy el taller se llena de gente: ¡es la <b>competición de sumo de robots</b>! Dos robots entran en un círculo, el <b>dohyo</b>, y cada uno intenta sacar al otro empujándolo. Quien sale del círculo, pierde. Antes de la competición, entrenaremos con latas y con el <b>muñeco de entrenamiento</b>, una caja que hace de rival." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Dohyo|Dohyo', t: 'El camp de la competició|El campo de la competición', anim: 'k7ring',
          x: "El <b>dohyo</b> de la nostra competició és un cercle blanc amb una <b>vora negra</b>. Està una mica enlairat: més enllà de la vora hi ha el buit. Els sensors de línia del Maqueen donen <b>0 al blanc</b> i <b>1 a la vora negra</b> (i també a l'aire). Per això, quan L o R valen 1, el robot sap que és a punt de caure i ha de <b>retrocedir</b>.|El <b>dohyo</b> de nuestra competición es un círculo blanco con un <b>borde negro</b>. Está un poco elevado: más allá del borde está el vacío. Los sensores de línea del Maqueen dan <b>0 en el blanco</b> y <b>1 en el borde negro</b> (y también en el aire). Por eso, cuando L o R valen 1, el robot sabe que está a punto de caer y tiene que <b>retroceder</b>.",
          tip: "El nostre dohyo fa 76 cm d'ample: el Maqueen hi cap moltes vegades! A moltes competicions de veritat els colors són al revés (negre amb la vora blanca) i el programa s'hi ha d'adaptar.|Nuestro dohyo mide 76 cm de ancho: ¡el Maqueen cabe muchas veces! En muchas competiciones de verdad los colores son al revés (negro con el borde blanco) y el programa se tiene que adaptar." },
        { k: 'No caure|No caer', t: 'Retrocedeix a la vora|Retrocede en el borde',
          robo: { w: { ...DOHYO, bot: [50, 45, 30], time: 20 }, prog: 'forever{ if:L=1||R=1{ run:all,back,150 wait:500 run:L,fwd,100 run:R,back,100 wait:800 } else{ run:all,fwd,150 } }' },
          x: "La primera regla del sumo és <b>no sortir mai</b>. Amb un «si» i la condició <b>L = 1 o R = 1</b>: si algun sensor veu negre, enrere un moment i gira; si no, endavant. Així el robot pot passar-se tota la competició dins el cercle.|La primera regla del sumo es <b>no salir nunca</b>. Con un «si» y la condición <b>L = 1 o R = 1</b>: si algún sensor ve negro, atrás un momento y gira; si no, adelante. Así el robot puede pasarse toda la competición dentro del círculo." },
        { k: 'Buscar|Buscar', t: 'On és el rival?|¿Dónde está el rival?', anim: 'k7sumo',
          x: "Per trobar el rival, el robot <b>gira sobre si mateix</b> com un far mentre els ultrasons miren endavant. Tot el dohyo fa menys de 80 cm: si la distància és <b>menor de 60</b>, hi ha alguna cosa al davant. Llavors: <b>atac</b> a velocitat 255!|Para encontrar al rival, el robot <b>gira sobre sí mismo</b> como un faro mientras los ultrasonidos miran adelante. Todo el dohyo mide menos de 80 cm: si la distancia es <b>menor de 60</b>, hay algo delante. Entonces: ¡<b>ataque</b> a velocidad 255!" },
        { k: 'Atacar|Atacar', t: 'Busca, ataca i no caiguis|Busca, ataca y no te caigas',
          robo: { w: { ...DOHYO, bot: [50, 45, 0], objs: [ninot(70, 60)], time: 15 }, prog: SUMO },
          x: "El programa complet té tres «si», un dins de l'altre: <b>1.</b> si veu la vora, enrere una mica; <b>2.</b> si no, i veu el rival, endavant a 255; <b>3.</b> si no veu res, gira per buscar. El robot ho comprova 50 vegades per segon.|El programa completo tiene tres «si», uno dentro del otro: <b>1.</b> si ve el borde, atrás un poco; <b>2.</b> si no, y ve al rival, adelante a 255; <b>3.</b> si no ve nada, gira para buscar. El robot lo comprueba 50 veces por segundo.",
          tip: "Si l'empenta no el treu, el robot retrocedeix poc i torna a atacar: insistir funciona!|Si el empujón no lo saca, el robot retrocede poco y vuelve a atacar: ¡insistir funciona!" },
        { k: 'Compte!|¡Cuidado!', t: "L'ordre dels «si» importa|El orden de los «si» importa",
          robo: { w: { ...DOHYO, bot: [50, 45, 0], objs: [can(50, 25)], time: 10 }, prog: 'forever{ if:dist<60{ run:all,fwd,255 } else{ if:L=1||R=1{ run:all,back,150 wait:300 } else{ run:L,fwd,90 run:R,back,90 } } }' },
          x: "Aquí el «si veu el rival» va <b>primer</b>. El robot empeny la llauna fins a la vora… i com que encara la veu, continua atacant i <b>cau</b> darrere seu! La vora no es comprova mai mentre ataca.|Aquí el «si ve al rival» va <b>primero</b>. El robot empuja la lata hasta el borde… ¡y como todavía la ve, sigue atacando y <b>cae</b> detrás de ella! El borde no se comprueba nunca mientras ataca.",
          bad: "L'ordre dels «si» no canvia res.|El orden de los «si» no cambia nada.", good: "El primer «si» és el que mana: posa-hi la seguretat (la vora).|El primer «si» es el que manda: pon en él la seguridad (el borde)." }
      ] },
      { k: 'quiz', ph: 'prova', q: "En el programa de sumo, per què el «si L = 1 o R = 1» ha d'anar <b>el primer</b>?|En el programa de sumo, ¿por qué el «si L = 1 o R = 1» tiene que ir <b>el primero</b>?",
        opts: ["Perquè no sortir del dohyo és més important que atacar|Porque no salir del dohyo es más importante que atacar", 'Perquè així el robot va més de pressa|Porque así el robot va más deprisa', 'Perquè els sensors de línia només funcionen al principi|Porque los sensores de línea solo funcionan al principio'], a: 0,
        ex: "Quan es compleix el primer «si», els altres ni es miren. Per això hi posem el més important: la seguretat.|Cuando se cumple el primer «si», los demás ni se miran. Por eso ponemos en él lo más importante: la seguridad." },
      { k: 'unplug', ph: 'mans', ico: '⭕', title: 'El dohyo de corda|El dohyo de cuerda',
        t: "Amb algú de casa, una corda o una bufanda llarga, i un coixí. Feu un cercle a terra amb la corda, d'uns dos metres, en un lloc sense mobles a prop.|Con alguien de casa, una cuerda o una bufanda larga, y un cojín. Haced un círculo en el suelo con la cuerda, de unos dos metros, en un sitio sin muebles cerca.",
        steps: ["Una persona fa de <b>robot</b>: ulls tancats, braços endavant, i camina a poc a poc. L'altra fa de <b>sensors</b>: només pot dir «vora!» (quan un peu toca la corda) o «rival al davant!».|Una persona hace de <b>robot</b>: ojos cerrados, brazos adelante, y camina despacio. La otra hace de <b>sensores</b>: solo puede decir «¡borde!» (cuando un pie toca la cuerda) o «¡rival delante!».",
          "El robot segueix l'estratègia: amb «vora!», dos passets enrere i un quart de volta; amb «rival al davant!», endavant fins a empènyer el coixí; si no sent res, gira a poc a poc sobre el lloc.|El robot sigue la estrategia: con «¡borde!», dos pasitos atrás y un cuarto de vuelta; con «¡rival delante!», adelante hasta empujar el cojín; si no oye nada, gira despacio sobre el sitio.",
          'La missió: treure el coixí fora del cercle sense trepitjar fora. Després canvieu els papers.|La misión: sacar el cojín fuera del círculo sin pisar fuera. Después cambiad los papeles.',
          'Proveu-ho dient els avisos tard: què passa?|Probadlo diciendo los avisos tarde: ¿qué pasa?'],
        tip: "Si l'avís de la vora arriba tard, el robot cau: per això, al programa, la vora va primer.|Si el aviso del borde llega tarde, el robot cae: por eso, en el programa, el borde va primero." },
      { k: 'rpredict', ph: 'prova', q: "El robot avança fins que un sensor de línia veu la vora i llavors va enrere durant 1 segon. <b>On s'aturarà?</b>|El robot avanza hasta que un sensor de línea ve el borde y entonces va atrás durante 1 segundo. <b>¿Dónde se parará?</b>",
        w: { ...DOHYO, bot: [50, 45, 0], marks: { A: [50, 12], B: [50, 27], C: [50, 45] } }, scripts: ['start'],
        prog: 'start{ run:all,fwd,150 until:L=1||R=1{ wait:10 } run:all,back,150 wait:1000 stop:all }', a: 'B',
        ex: "Arriba a prop de la vora (A), on els sensors veuen el negre, i després recula uns 15 cm fins a la B. Ni cau ni torna al centre.|Llega cerca del borde (A), donde los sensores ven el negro, y después recula unos 15 cm hasta la B. Ni cae ni vuelve al centro." },
      { k: 'rspot', ph: 'investiga', q: "Aquest és el robot de sumo. <b>Toca el bloc que el salva de caure</b> quan arriba a la vora.|Este es el robot de sumo. <b>Toca el bloque que lo salva de caer</b> cuando llega al borde.",
        w: { ...DOHYO, bot: [50, 45, 0], objs: [ninot(70, 60)], time: 15 },
        prog: 'forever{ if:L=1||R=1{ run:all,back,150! wait:200 run:L,fwd,100 run:R,back,100 wait:200 } else{ if:dist<60{ run:all,fwd,255 } else{ run:L,fwd,90 run:R,back,90 } } }',
        yes: "Molt bé! Els motors enrere el porten cap a dins del dohyo.|¡Muy bien! Los motores atrás lo llevan hacia dentro del dohyo.",
        ex: "És «motor els dos enrere», just dins del «si L = 1 o R = 1»: quan veu la vora, recula cap al centre.|Es «motor los dos atrás», justo dentro del «si L = 1 o R = 1»: cuando ve el borde, recula hacia el centro." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Postura de sumo! Cames obertes, genolls una mica doblegats, mans endavant. Quan algú digui «vora!», un salt petit enrere; quan digui «rival!», dos passets endavant empenyent l'aire; amb «busca!», gira al lloc. Cada vegada més de pressa!|¡Postura de sumo! Piernas abiertas, rodillas un poco dobladas, manos adelante. Cuando alguien diga «¡borde!», un salto pequeño atrás; cuando diga «¡rival!», dos pasitos adelante empujando el aire; con «¡busca!», gira en el sitio. ¡Cada vez más deprisa!" },
      { k: 'robo', ph: 'repte', q: "<b>Entrenament 1: no surtis!</b> Aquest robot va endavant i cau del dohyo. Fes que hi passegi <b>20 segons</b> sense sortir-ne, recorrent almenys 150 cm.|<b>Entrenamiento 1: ¡no salgas!</b> Este robot va adelante y cae del dohyo. Haz que se pasee por él <b>20 segundos</b> sin salir, recorriendo al menos 150 cm.",
        w: { ...DOHYO, bot: [50, 45, 30], goal: [{ k: 'inring' }, { k: 'dist', min: 150 }], time: 20 },
        pal: ['run', 'stop', 'wait', 'if', 'else', 'and'], ops: ['L', 'M', 'R'], scripts: ['forever'],
        prog: 'forever{ run:all,fwd,150 }', sol: 'forever{ if:L=1||R=1{ run:all,back,150 wait:500 run:L,fwd,100 run:R,back,100 wait:800 } else{ run:all,fwd,150 } }',
        hint: "Posa un «si» amb «si no». La condició: L = 1, i amb «Afegeix i / o» tria «o» i R = 1. Al «si»: enrere uns 500 ms i gira uns 800 ms. Al «si no»: endavant.|Pon un «si» con «si no». La condición: L = 1, y con «Añade y / o» elige «o» y R = 1. En el «si»: atrás unos 500 ms y gira unos 800 ms. En el «si no»: adelante." },
      { k: 'robo', ph: 'repte', q: "<b>Entrenament 2: fora la llauna!</b> Hi ha una llauna al davant, però a cada pista el robot surt d'un lloc diferent. Empeny-la fora, <b>retrocedeix</b> sense caure i atura't.|<b>Entrenamiento 2: ¡fuera la lata!</b> Hay una lata delante, pero en cada pista el robot sale de un sitio diferente. Empújala fuera, <b>retrocede</b> sin caer y párate.",
        w: { ...DOHYO, bot: [50, 60, 0], objs: [can(50, 40)], goal: [{ k: 'out', n: 1 }, { k: 'inring' }, { k: 'stopped' }], time: 15,
          alts: [{ bot: [50, 32, 0], objs: [can(50, 20)] }, { bot: [50, 75, 0], objs: [can(50, 30)] }] },
        pal: ['run', 'stop', 'wait', 'until', 'and'], ops: ['L', 'M', 'R'], scripts: ['start'],
        sol: 'start{ run:all,fwd,150 until:L=1||R=1{ wait:10 } run:all,back,150 wait:800 stop:all }',
        hint: "Engega els motors endavant i fes servir «repeteix fins que L = 1 o R = 1» (amb una espera curta a dins). Després: enrere 800 ms i atura.|Enciende los motores adelante y usa «repite hasta que L = 1 o R = 1» (con una espera corta dentro). Después: atrás 800 ms y para." },
      { k: 'robo', ph: 'repte', q: "<b>Entrenament 3: busca el ninot!</b> El ninot d'entrenament és a un lloc diferent a cada pista. El teu robot l'ha de <b>buscar</b> amb els ultrasons, <b>empènyer-lo fora</b> i no sortir mai del dohyo.|<b>Entrenamiento 3: ¡busca el muñeco!</b> El muñeco de entrenamiento está en un sitio diferente en cada pista. Tu robot tiene que <b>buscarlo</b> con los ultrasonidos, <b>empujarlo fuera</b> y no salir nunca del dohyo.",
        w: { ...DOHYO, bot: [50, 45, 0], objs: [ninot(50, 25)], goal: [{ k: 'out', n: 1 }, { k: 'inring' }], time: 25,
          alts: [{ objs: [ninot(75, 50)] }, { objs: [ninot(32, 66)] }, { objs: [ninot(62, 62)] }] },
        pal: ['run', 'stop', 'wait', 'if', 'else', 'and'], ops: ['dist', 'L', 'M', 'R'], scripts: ['forever'],
        sol: SUMO,
        hint: "Tres «si», en aquest ordre: 1) si L = 1 o R = 1, enrere 200 ms i gira 200 ms; 2) si no, si distància < 60, endavant a 255; 3) si no, gira sobre si mateix a 90. Retrocedir <b>poc</b> ajuda a tornar a atacar.|Tres «si», en este orden: 1) si L = 1 o R = 1, atrás 200 ms y gira 200 ms; 2) si no, si distancia < 60, adelante a 255; 3) si no, gira sobre sí mismo a 90. Retroceder <b>poco</b> ayuda a volver a atacar." },
      { k: 'robo', ph: 'repte', q: "<b>Neteja el dohyo!</b> Abans de la competició, cal treure <b>les tres llaunes</b> que hi han quedat, sense caure. Prova el teu programa de sumo a les dues pistes (45 segons).|<b>¡Limpia el dohyo!</b> Antes de la competición, hay que sacar <b>las tres latas</b> que se han quedado, sin caer. Prueba tu programa de sumo en las dos pistas (45 segundos).",
        w: { ...DOHYO, bot: [50, 45, 0], objs: [can(50, 22), can(72, 50), can(34, 62)], goal: [{ k: 'out', n: 3 }, { k: 'inring' }], time: 45,
          alts: [{ objs: [can(60, 25), can(30, 50), can(65, 65)] }] },
        pal: ['run', 'stop', 'wait', 'if', 'else', 'and'], ops: ['dist', 'L', 'M', 'R'], scripts: ['forever'],
        sol: SUMO,
        hint: "Serveix el mateix programa del ninot. Si alguna llauna se li resisteix, fes que retrocedeixi poc (200 ms), giri poc (200 ms) i busqui girant a velocitat 90.|Sirve el mismo programa del muñeco. Si alguna lata se le resiste, haz que retroceda poco (200 ms), gire poco (200 ms) y busque girando a velocidad 90." },
      { k: 'rcreate', ph: 'crea', name: 'El meu campió de sumo|Mi campeón de sumo',
        q: "<b>Prepara el teu robot per a la competició!</b> Ha de guanyar al ninot a les tres pistes i, com els robots de sumo de veritat, posar els <b>llums del cotxe vermells</b> quan ataca. Pots canviar les velocitats, els temps i la manera de buscar.|<b>¡Prepara tu robot para la competición!</b> Tiene que ganar al muñeco en las tres pistas y, como los robots de sumo de verdad, poner las <b>luces del coche rojas</b> cuando ataca. Puedes cambiar las velocidades, los tiempos y la manera de buscar.",
        crit: ['Treu el ninot del dohyo a les tres pistes|Saca el muñeco del dohyo en las tres pistas', 'No surt mai del dohyo|No sale nunca del dohyo', 'Els llums del cotxe es posen vermells quan ataca|Las luces del coche se ponen rojas cuando ataca'],
        w: { ...DOHYO, bot: [50, 45, 0], objs: [ninot(66, 30)], goal: [{ k: 'out', n: 1 }, { k: 'inring' }], time: 25, alts: [{ objs: [ninot(28, 52)] }, { objs: [ninot(55, 72)] }] },
        pal: ['run', 'stop', 'wait', 'if', 'else', 'and', 'car', 'icon', 'note'], ops: ['dist', 'L', 'M', 'R'], scripts: ['start', 'forever'],
        sol: 'forever{ if:L=1||R=1{ run:all,back,150 wait:200 run:L,fwd,100 run:R,back,100 wait:200 } else{ if:dist<60{ car:all,red run:all,fwd,255 } else{ car:all,blue run:L,fwd,90 run:R,back,90 } } }',
        check(P) { let ok = false; const w = l => (l || []).forEach(b => { if (b.k === 'car' && b.c === 'red') ok = true; w(b.b); w(b.e); }); Object.values(P).forEach(w);
          return ok ? null : "Guanya, però falten els llums vermells! Posa «llums del cotxe vermell» a la branca on ataca.|¡Gana, pero faltan las luces rojas! Pon «luces del coche rojo» en la rama donde ataca."; } },
      { k: 'quiz', ph: 'tanca', q: "El robot de sumo <b>no veu res</b> amb els ultrasons i no és a la vora. Què fa?|El robot de sumo <b>no ve nada</b> con los ultrasonidos y no está en el borde. ¿Qué hace?",
        opts: ['Gira sobre si mateix per buscar el rival|Gira sobre sí mismo para buscar al rival', 'Ataca a velocitat 255|Ataca a velocidad 255', "S'atura i espera|Se para y espera"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Per què diem que el sumo de robots és una <b>competició</b> amb regles?|¿Por qué decimos que el sumo de robots es una <b>competición</b> con reglas?",
        opts: ["Perquè els dos robots tenen la mateixa missió i guanya qui la compleix: treure l'altre del dohyo sense sortir-ne|Porque los dos robots tienen la misma misión y gana quien la cumple: sacar al otro del dohyo sin salir", 'Perquè guanya el robot més car|Porque gana el robot más caro', 'Perquè els robots es poden fer mal|Porque los robots se pueden hacer daño'], a: 0,
        ex: "A les competicions de robots, tots segueixen les mateixes regles i guanya la millor estratègia, no la més forta.|En las competiciones de robots, todos siguen las mismas reglas y gana la mejor estrategia, no la más fuerte." },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 3 · Rescat ---------- */
  { id: 'k7-3', t: 'Rescat a la cova|Rescate en la cueva', min: 45, badge: 'k_rescat',
    learn: ["El Maqueen no té pinça: per portar un objecte l'empeny en línia recta, ben de cara.|El Maqueen no tiene pinza: para llevar un objeto lo empuja en línea recta, bien de cara.",
      "El valor analògic (ADC) del sensor de línia distingeix el blanc (~90) d'una zona de color (~360): així el robot sap que és a la base.|El valor analógico (ADC) del sensor de línea distingue el blanco (~90) de una zona de color (~360): así el robot sabe que está en la base.",
      "Una missió llarga es divideix en fases: buscar, apuntar, empènyer, deixar i avisar.|Una misión larga se divide en fases: buscar, apuntar, empujar, dejar y avisar."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "En el robot de sumo, quin «si» anava el primer?|En el robot de sumo, ¿qué «si» iba el primero?",
        opts: ['El de la vora: si L = 1 o R = 1, enrere|El del borde: si L = 1 o R = 1, atrás', 'El del rival: si distància < 60, ataca|El del rival: si distancia < 60, ataca', 'El de buscar: gira sobre si mateix|El de buscar: gira sobre sí mismo'], a: 0 },
      { k: 'quiz', ph: 'recorda', q: "El sensor de línia també dona un valor analògic (ADC). Quin valor dona, més o menys, sobre una <b>zona de color</b>?|El sensor de línea también da un valor analógico (ADC). ¿Qué valor da, más o menos, sobre una <b>zona de color</b>?",
        opts: ['Uns 360: entre el blanc (~90) i el negre (~900)|Unos 360: entre el blanco (~90) y el negro (~900)', 'Exactament 0|Exactamente 0', 'Sempre 500|Siempre 500'], a: 0 },
      { k: 'story', ph: 'missio', who: 'both', scene: 'illa', title: 'La cova del far|La cueva del faro',
        t: "Alerta a l'illa! Un equip d'exploradors ha deixat les seves <b>balises</b> (unes boles de senyal) dins la cova del far, i ara el túnel és massa estret per a les persones. El Maqueen sí que hi cap! La missió: trobar cada balisa i <b>empènyer-la fins a la base</b> blava, on l'equip la recollirà.|¡Alerta en la isla! Un equipo de exploradores ha dejado sus <b>balizas</b> (unas bolas de señal) dentro de la cueva del faro, y ahora el túnel es demasiado estrecho para las personas. ¡El Maqueen sí que cabe! La misión: encontrar cada baliza y <b>empujarla hasta la base</b> azul, donde el equipo la recogerá." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Empènyer|Empujar', t: 'Sense pinça, de cara|Sin pinza, de cara', anim: 'k7push',
          x: "El Maqueen no té pinça ni braç: per portar la balisa, l'<b>empeny</b> amb el davant. Si la toca <b>ben de cara</b>, la balisa va recta davant del robot. Si la toca de costat, rellisca i se'n va cap a un lloc! Per això, empènyer funciona en <b>línia recta</b>.|El Maqueen no tiene pinza ni brazo: para llevar la baliza, la <b>empuja</b> con la parte de delante. Si la toca <b>bien de cara</b>, la baliza va recta delante del robot. ¡Si la toca de lado, resbala y se va hacia un lado! Por eso, empujar funciona en <b>línea recta</b>." },
        { k: 'La base|La base', t: 'Com sap que ha arribat?|¿Cómo sabe que ha llegado?',
          robo: { w: { w: 140, h: 50, bot: [14, 25, 90], objs: [{ x: 32, y: 25, r: 3, kind: 'ball' }], ...BASE(70) }, prog: 'start{ run:all,fwd,150 until:aM>200{ wait:10 } wait:300 stop:all }' },
          x: "La base és una zona <b>blava</b>. Els sensors de línia hi veuen un valor analògic d'uns <b>360</b>, i al blanc, uns <b>90</b>. Amb «repeteix fins que línia M (ADC) > 200», el robot empeny fins que el davant entra a la base. Com que la balisa va al davant, ja hi és a dins!|La base es una zona <b>azul</b>. Los sensores de línea ven en ella un valor analógico de unos <b>360</b>, y en el blanco, unos <b>90</b>. Con «repite hasta que línea M (ADC) > 200», el robot empuja hasta que la parte de delante entra en la base. ¡Como la baliza va delante, ya está dentro!",
          tip: "Una espera curta (300 ms) després de veure la base la fica una mica més endins.|Una espera corta (300 ms) después de ver la base la mete un poco más adentro." },
        { k: 'Buscar|Buscar', t: 'Gira fins que la veus|Gira hasta que la ves',
          robo: { w: { w: 100, h: 80, bot: [50, 40, 0], ...COVA(150) }, prog: BUSCA(60) },
          x: "A la cova, el robot no sap on és la balisa. Gira sobre si mateix <b>fins que</b> els ultrasons veuen alguna cosa a menys de 25 cm (les parets són més lluny). Llavors ja la té de cara: endavant, fins a la base!|En la cueva, el robot no sabe dónde está la baliza. Gira sobre sí mismo <b>hasta que</b> los ultrasonidos ven algo a menos de 25 cm (las paredes están más lejos). Entonces ya la tiene de cara: ¡adelante, hasta la base!" },
        { k: 'Fases|Fases', t: 'Una missió, molts trossos|Una misión, muchos trozos', anim: 'k7plan',
          x: "Una missió llarga es resol <b>per fases</b>, una darrere l'altra: <b>buscar</b> (girar fins que la veu), <b>empènyer</b> (endavant fins a la base), <b>deixar</b> (aturar-se) i <b>avisar</b> (llums, icona i so). Cada fase és un tros del programa dins d'«en iniciar», i cada «repeteix fins que» espera que la fase acabi.|Una misión larga se resuelve <b>por fases</b>, una detrás de otra: <b>buscar</b> (girar hasta que la ve), <b>empujar</b> (adelante hasta la base), <b>dejar</b> (pararse) y <b>avisar</b> (luces, icono y sonido). Cada fase es un trozo del programa dentro de «al iniciar», y cada «repite hasta que» espera a que la fase termine." },
        { k: 'Compte!|¡Cuidado!', t: 'Als revolts, la balisa s\'escapa|En las curvas, la baliza se escapa',
          robo: { w: { w: 150, h: 80, bot: [14, 60, 90], lines: [{ p: [[12, 60], [50, 60], [70, 40], [110, 40], [128, 22]], w: 2 }], objs: [{ x: 30, y: 60, r: 3, kind: 'can' }], time: 14 }, prog: 'forever{ if:L=1&&R=0{ run:L,fwd,40 run:R,fwd,140 } else{ if:R=1&&L=0{ run:L,fwd,140 run:R,fwd,40 } else{ run:all,fwd,120 } } }' },
          x: "Aquest robot segueix la línia perfectament… però al primer revolt la llauna continua recta i <b>es queda enrere</b>. Sense pinça, un objecte rodó no gira amb el robot.|Este robot sigue la línea perfectamente… pero en la primera curva la lata sigue recta y <b>se queda atrás</b>. Sin pinza, un objeto redondo no gira con el robot.",
          bad: "Si el robot gira, la balisa gira amb ell.|Si el robot gira, la baliza gira con él.", good: "Primer apunta cap a la base i després empeny en línia recta.|Primero apunta hacia la base y después empuja en línea recta." }
      ] },
      { k: 'seq', ph: 'mans', q: "Ordena les fases de la missió de rescat.|Ordena las fases de la misión de rescate.",
        items: ['Buscar: girar fins que els ultrasons veuen la balisa|Buscar: girar hasta que los ultrasonidos ven la baliza', 'Empènyer: endavant, ben de cara|Empujar: adelante, bien de cara', 'Arribar: el sensor veu el color de la base|Llegar: el sensor ve el color de la base', 'Deixar: atura els motors|Dejar: para los motores', "Avisar: llums verds, icona i so|Avisar: luces verdes, icono y sonido"],
        ex: "Cada fase comença quan s'acaba l'anterior. Si te'n saltes una, la missió falla.|Cada fase empieza cuando termina la anterior. Si te saltas una, la misión falla." },
      { k: 'unplug', ph: 'mans', ico: '📦', title: 'Empènyer sense pinça|Empujar sin pinza',
        t: "Necessites una capsa de sabates (sense tapa), una pilota petita o una taronja, i un passadís lliure. Marca una «base» a terra amb un full de paper.|Necesitas una caja de zapatos (sin tapa), una pelota pequeña o una naranja, y un pasillo libre. Marca una «base» en el suelo con una hoja de papel.",
        steps: ["Posa la capsa de lat, amb el costat obert mirant endavant: és el davant del robot. Empeny la pilota en <b>línia recta</b> fins a la base.|Pon la caja de lado, con el lado abierto mirando adelante: es la parte delantera del robot. Empuja la pelota en <b>línea recta</b> hasta la base.",
          "Ara prova d'empènyer-la tocant-la només amb una <b>cantonada</b> de la capsa. Cap on se'n va?|Ahora prueba a empujarla tocándola solo con una <b>esquina</b> de la caja. ¿Hacia dónde se va?",
          "Posa la base darrere d'un revolt i intenta portar-hi la pilota girant mentre empenys. Quantes vegades se t'escapa?|Pon la base detrás de una curva e intenta llevar la pelota girando mientras empujas. ¿Cuántas veces se te escapa?",
          "Inventa una manera que funcioni sempre: apuntar primer i després empènyer recte!|Inventa una manera que funcione siempre: ¡apuntar primero y después empujar recto!"],
        tip: "Una capsa amb el costat obert fa de «pala» i la pilota s'escapa menys. Alguns robots de rescat porten una pala així!|Una caja con el lado abierto hace de «pala» y la pelota se escapa menos. ¡Algunos robots de rescate llevan una pala así!" },
      { k: 'rpredict', ph: 'prova', q: "El robot empeny la balisa <b>fins que</b> el sensor del mig veu el color de la base, i llavors s'atura. <b>On s'aturarà el robot?</b>|El robot empuja la baliza <b>hasta que</b> el sensor del medio ve el color de la base, y entonces se para. <b>¿Dónde se parará el robot?</b>",
        w: { w: 130, h: 50, bot: [14, 25, 90], objs: [{ x: 34, y: 25, r: 3, kind: 'ball' }], ...BASE(80), marks: { A: [56, 25], B: [77, 25], C: [91, 25] } }, scripts: ['start'],
        prog: 'start{ run:all,fwd,150 until:aM>200{ wait:10 } stop:all }', a: 'B',
        ex: "Els sensors són al davant del robot: veuen el blau quan el centre del robot encara és fora, just a tocar de la base (B). La balisa, que va al davant, ja és a dins!|Los sensores están delante del robot: ven el azul cuando el centro del robot todavía está fuera, justo al lado de la base (B). ¡La baliza, que va delante, ya está dentro!" },
      { k: 'rspot', ph: 'investiga', q: "Aquest és el programa de la cova. <b>Toca el bloc que fa la fase «buscar»</b>: el que espera fins que el robot té la balisa de cara.|Este es el programa de la cueva. <b>Toca el bloque que hace la fase «buscar»</b>: el que espera hasta que el robot tiene la baliza de cara.",
        w: { w: 100, h: 80, bot: [50, 40, 0], ...COVA(250) }, scripts: ['start'],
        prog: 'start{ run:L,fwd,60 run:R,back,60 until:dist<25!{ wait:10 } run:all,fwd,120 until:aM>200{ wait:10 } wait:300 stop:all }',
        yes: "Exacte! Mentre els ultrasons no vegin res a menys de 25 cm, el robot continua girant.|¡Exacto! Mientras los ultrasonidos no vean nada a menos de 25 cm, el robot sigue girando.",
        ex: "És «repeteix fins que distància < 25»: els motors ja giren i aquest bloc espera fins que la balisa és al davant.|Es «repite hasta que distancia < 25»: los motores ya giran y este bloque espera hasta que la baliza está delante." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Fes de robot de rescat! Ulls tancats i gira al lloc a poc a poc, amb el braç estirat com un sensor. Quan algú digui «balisa!», para i fes tres passos endavant al lloc. Amb «base!», atura't i aixeca els dos braços: rescat completat!|¡Haz de robot de rescate! Ojos cerrados y gira en el sitio despacio, con el brazo estirado como un sensor. Cuando alguien diga «¡baliza!», para y da tres pasos adelante en el sitio. Con «¡base!», párate y levanta los dos brazos: ¡rescate completado!" },
      { k: 'robo', ph: 'repte', q: "<b>La primera balisa.</b> És just al davant del robot i la base és al fons del túnel. Empeny-la fins a la base i atura't, sense xocar.|<b>La primera baliza.</b> Está justo delante del robot y la base está al fondo del túnel. Empújala hasta la base y párate, sin chocar.",
        w: { w: 130, h: 50, bot: [14, 25, 90], objs: [{ x: 34, y: 25, r: 3, kind: 'ball' }], ...BASE(92), goal: [{ k: 'push', obj: 0, id: 'base' }, { k: 'stopped' }, { k: 'nohit' }], time: 15 },
        pal: ['run', 'stop', 'wait'], ops: [], scripts: ['start'],
        sol: 'start{ run:all,fwd,150 wait:5000 stop:all }',
        hint: "A velocitat 150, el robot fa uns 15 cm cada segon. La balisa ha d'avançar uns 65 cm: prova amb una espera d'uns 5000 ms.|A velocidad 150, el robot hace unos 15 cm cada segundo. La baliza tiene que avanzar unos 65 cm: prueba con una espera de unos 5000 ms." },
      { k: 'robo', ph: 'repte', q: "<b>On és la base?</b> L'equip ha mogut la base, i a cada pista és a una distància diferent. Fes servir el <b>sensor de línia M (ADC)</b> per saber quan hi arribes.|<b>¿Dónde está la base?</b> El equipo ha movido la base, y en cada pista está a una distancia diferente. Usa el <b>sensor de línea M (ADC)</b> para saber cuándo llegas.",
        w: { w: 140, h: 50, bot: [14, 25, 90], objs: [{ x: 32, y: 25, r: 3, kind: 'ball' }], ...BASE(70), goal: [{ k: 'push', obj: 0, id: 'base' }, { k: 'stopped' }, { k: 'nohit' }], time: 15, alts: [BASE(100), BASE(52)] },
        pal: ['run', 'stop', 'wait', 'until'], ops: ['aM'], scripts: ['start'],
        prog: 'start{ run:all,fwd,150 wait:5000 stop:all }',
        sol: 'start{ run:all,fwd,150 until:aM>200{ wait:10 } wait:300 stop:all }',
        hint: "Engega els motors i posa «repeteix fins que línia M (ADC) > 200» amb una espera curta a dins. Després, espera 300 ms i atura.|Enciende los motores y pon «repite hasta que línea M (ADC) > 200» con una espera corta dentro. Después, espera 300 ms y para." },
      { k: 'robo', ph: 'repte', q: "<b>Busca a la cova.</b> El robot és al mig de la cova i la balisa pot ser a qualsevol costat (la base sempre és darrere de la balisa). Gira fins que la vegis, empeny-la fins a la base i atura't. Quatre pistes!|<b>Busca en la cueva.</b> El robot está en el medio de la cueva y la baliza puede estar en cualquier lado (la base siempre está detrás de la baliza). Gira hasta que la veas, empújala hasta la base y párate. ¡Cuatro pistas!",
        w: { w: 100, h: 80, bot: [50, 40, 0], ...COVA(60), goal: [{ k: 'push', obj: 0, id: 'base' }, { k: 'stopped' }, { k: 'nohit' }], time: 25, alts: [COVA(150), COVA(250), COVA(320)] },
        pal: ['run', 'stop', 'wait', 'until'], ops: ['dist', 'aM'], scripts: ['start'],
        sol: BUSCA(60),
        hint: "Fase 1: motor esquerre endavant i dret enrere a 60, i «repeteix fins que distància < 25». Fase 2: els dos endavant a 120 i «repeteix fins que línia M (ADC) > 200». Fase 3: espera 300 ms i atura.|Fase 1: motor izquierdo adelante y derecho atrás a 60, y «repite hasta que distancia < 25». Fase 2: los dos adelante a 120 y «repite hasta que línea M (ADC) > 200». Fase 3: espera 300 ms y para." },
      { k: 'robo', ph: 'repte', q: "<b>Rescat amb avís.</b> Quan la balisa és a la base, l'equip ha de saber-ho de lluny: després d'aturar-te, posa els <b>llums del cotxe verds</b> i mostra la icona <b>«sí»</b>. Tres pistes amb la base a llocs diferents.|<b>Rescate con aviso.</b> Cuando la baliza está en la base, el equipo tiene que saberlo de lejos: después de pararte, pon las <b>luces del coche verdes</b> y muestra el icono <b>«sí»</b>. Tres pistas con la base en sitios diferentes.",
        w: { w: 140, h: 50, bot: [14, 25, 90], objs: [{ x: 32, y: 25, r: 3, kind: 'ball' }], ...BASE(70), goal: [{ k: 'push', obj: 0, id: 'base' }, { k: 'stopped' }, { k: 'car', c: 'green' }, { k: 'icon', ic: 'yes' }], time: 15, alts: [BASE(100), BASE(52)] },
        pal: ['run', 'stop', 'wait', 'until', 'car', 'icon', 'note'], ops: ['aM'], scripts: ['start'],
        sol: 'start{ run:all,fwd,150 until:aM>200{ wait:10 } wait:300 stop:all car:all,green icon:yes note:C5,1/2 }',
        hint: "Fes servir el programa d'abans i, després d'«atura», afegeix «llums del cotxe verd» i «mostra la icona sí». Si vols, també una nota!|Usa el programa de antes y, después de «para», añade «luces del coche verde» y «muestra el icono sí». ¡Si quieres, también una nota!" },
      { k: 'rcreate', ph: 'crea', name: 'Operació balisa|Operación baliza',
        q: "<b>La gran operació!</b> Programa la missió sencera: <b>busca</b> la balisa a la cova, <b>empeny-la</b> fins a la base, <b>atura't</b> i <b>avisa</b> amb llums, icona o so. Ha de funcionar a les tres pistes. Tu decideixes com avises!|<b>¡La gran operación!</b> Programa la misión entera: <b>busca</b> la baliza en la cueva, <b>empújala</b> hasta la base, <b>párate</b> y <b>avisa</b> con luces, icono o sonido. Tiene que funcionar en las tres pistas. ¡Tú decides cómo avisas!",
        crit: ['Troba la balisa a les tres pistes|Encuentra la baliza en las tres pistas', "La porta a la base i s'atura sense xocar|La lleva a la base y se para sin chocar", "Avisa amb llums, icona o so quan acaba|Avisa con luces, icono o sonido cuando termina"],
        w: { w: 100, h: 80, bot: [50, 40, 0], ...COVA(110), goal: [{ k: 'push', obj: 0, id: 'base' }, { k: 'stopped' }, { k: 'nohit' }], time: 25, alts: [COVA(200), COVA(290)] },
        pal: ['run', 'stop', 'wait', 'until', 'if', 'car', 'under', 'icon', 'note'], ops: ['dist', 'aM'], scripts: ['start'],
        sol: BUSCA(60, 'car:all,green icon:yes note:C5,1/2 note:G5,1/2 '),
        check(P) { return has(P, 'car') || has(P, 'icon') || has(P, 'note') || has(P, 'under') ? null : "Rescat fet, però l'equip no se n'ha assabentat! Afegeix un avís al final: llums, una icona o una nota.|Rescate hecho, ¡pero el equipo no se ha enterado! Añade un aviso al final: luces, un icono o una nota."; } },
      { k: 'quiz', ph: 'tanca', q: "Per què el Maqueen ha d'empènyer la balisa <b>en línia recta</b>?|¿Por qué el Maqueen tiene que empujar la baliza <b>en línea recta</b>?",
        opts: ["Perquè no té pinça: si gira, la balisa rellisca i s'escapa|Porque no tiene pinza: si gira, la baliza resbala y se escapa", 'Perquè els motors no poden girar mentre empenyen|Porque los motores no pueden girar mientras empujan', 'Perquè els ultrasons només funcionen en línia recta|Porque los ultrasonidos solo funcionan en línea recta'], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Amb quina condició el robot sap que ha arribat a la base de color?|¿Con qué condición sabe el robot que ha llegado a la base de color?",
        opts: ['Línia M (ADC) > 200|Línea M (ADC) > 200', 'Distància < 10|Distancia < 10', 'Línia M = 0|Línea M = 0'], a: 0,
        ex: "Al blanc el valor és d'uns 90 i al color, d'uns 360: 200 queda ben bé al mig.|En el blanco el valor es de unos 90 y en el color, de unos 360: 200 queda justo en medio." },
      { k: 'feel', ph: 'tanca' }
    ] },
  /* ---------- Sessió 4 · Projecte: la cursa contrarellotge ---------- */
  { id: 'k7-4', t: 'Projecte: la cursa contrarellotge|Proyecto: la carrera contrarreloj', min: 45, badge: 'k_cursa', proj: true,
    learn: ["En una contrarellotge, el robot ha de passar per tots els punts de control i aturar-se a la meta abans que s'acabi el temps.|En una contrarreloj, el robot tiene que pasar por todos los puntos de control y pararse en la meta antes de que se acabe el tiempo.",
      "«Repeteix fins que L = 1 i R = 1» segueix la línia fins a la ratlla de meta; després, un sol «atura» i el robot no torna a arrencar.|«Repite hasta que L = 1 y R = 1» sigue la línea hasta la raya de meta; después, un solo «para» y el robot no vuelve a arrancar.",
      "Anar més de pressa estalvia temps, però massa velocitat fa perdre la línia: cal provar, mesurar i millorar.|Ir más deprisa ahorra tiempo, pero demasiada velocidad hace perder la línea: hay que probar, medir y mejorar."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Al rescat, com sabia el robot que havia arribat a la base blava?|En el rescate, ¿cómo sabía el robot que había llegado a la base azul?",
        opts: ['El valor analògic del sensor de línia pujava per sobre de 200|El valor analógico del sensor de línea subía por encima de 200', 'Els ultrasons donaven 500|Los ultrasonidos daban 500', 'Comptava els segons|Contaba los segundos'], a: 0 },
      { k: 'quiz', ph: 'recorda', q: "El bloc «seguiment de línia activat» fa que el Maqueen segueixi la línia sol. Com va?|El bloque «seguimiento de línea activado» hace que el Maqueen siga la línea solo. ¿Cómo va?",
        opts: ['Segur, però a poc a poc|Seguro, pero despacio', 'A la velocitat màxima, 255|A la velocidad máxima, 255', "S'atura sol a la meta|Se para solo en la meta"], a: 0,
        ex: "El xip segueix la línia a una velocitat baixa i no s'atura mai sol: per a una cursa, ens caldrà el nostre programa.|El chip sigue la línea a una velocidad baja y no se para nunca solo: para una carrera, nos hará falta nuestro programa." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'moll', title: 'La gran cursa del port|La gran carrera del puerto',
        t: "Últim dia de la Setmana de les Missions: la <b>cursa contrarellotge</b> al circuit del moll! Cada robot surt sol, dona <b>una volta</b> al circuit de cinta negra, passa pels <b>punts de control</b> numerats i s'ha d'<b>aturar a la meta</b>. Guanya qui ho fa en menys temps… sense sortir-se'n. Aquest és el teu projecte de la unitat!|Último día de la Semana de las Misiones: ¡la <b>carrera contrarreloj</b> en el circuito del muelle! Cada robot sale solo, da <b>una vuelta</b> al circuito de cinta negra, pasa por los <b>puntos de control</b> numerados y se tiene que <b>parar en la meta</b>. Gana quien lo hace en menos tiempo… sin salirse. ¡Este es tu proyecto de la unidad!" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Contrarellotge|Contrarreloj', t: 'Ràpid… però sense perdre la línia|Rápido… pero sin perder la línea', anim: 'k7trial',
          x: "Com més de pressa va el robot, menys temps tarda. Però als <b>revolts</b> la línia s'escapa més aviat de sota els sensors, i el robot ha de corregir més ràpid. Si va massa de pressa, se'n surt o confon un revolt amb la meta. La millor velocitat no és la màxima: és la més ràpida que <b>sempre</b> funciona.|Cuanto más deprisa va el robot, menos tiempo tarda. Pero en las <b>curvas</b> la línea se escapa antes de debajo de los sensores, y el robot tiene que corregir más rápido. Si va demasiado deprisa, se sale o confunde una curva con la meta. La mejor velocidad no es la máxima: es la más rápida que <b>siempre</b> funciona." },
        { k: 'Meta|Meta', t: 'La ratlla de meta|La raya de meta',
          robo: { w: { w: 140, h: 80, ...CA, goal: [{ k: 'cps', pts: CA_CP, r: 7 }], time: 18 }, prog: CURSA(200, 40, 200) },
          x: "La meta és una <b>ratlla de cinta</b> que travessa el circuit. Durant la volta, els sensors L i R mai no són negres a la vegada (la línia és més estreta que la distància entre ells); a la ratlla, <b>sí</b>! Per això el robot segueix la línia <b>fins que L = 1 i R = 1</b>, i llavors s'atura.|La meta es una <b>raya de cinta</b> que atraviesa el circuito. Durante la vuelta, los sensores L y R nunca son negros a la vez (la línea es más estrecha que la distancia entre ellos); ¡en la raya, <b>sí</b>! Por eso el robot sigue la línea <b>hasta que L = 1 y R = 1</b>, y entonces se para.",
          tip: "Els cercles numerats són els punts de control: el robot hi ha de passar en ordre.|Los círculos numerados son los puntos de control: el robot tiene que pasar por ellos en orden." },
        { k: 'El xip|El chip', t: 'Seguiment del xip: lent i sense meta|Seguimiento del chip: lento y sin meta',
          robo: { w: { w: 140, h: 80, ...CA, goal: [{ k: 'cps', pts: CA_CP, r: 7 }], time: 18 }, prog: 'start{ patrol:on }' },
          x: "El seguiment de línia del xip és molt segur, però va a poc a poc: tarda uns <b>40 segons</b> per volta! I no sap que hi ha una meta: passa per sobre de la ratlla i continua. El nostre programa, a velocitat 200, la fa en uns <b>15 segons</b> i s'atura.|El seguimiento de línea del chip es muy seguro, pero va despacio: ¡tarda unos <b>40 segundos</b> por vuelta! Y no sabe que hay una meta: pasa por encima de la raya y sigue. Nuestro programa, a velocidad 200, la hace en unos <b>15 segundos</b> y se para." },
        { k: 'Compte!|¡Cuidado!', t: 'Frenar no és instantani|Frenar no es instantáneo',
          robo: { w: { w: 140, h: 80, ...CA, goal: [{ k: 'cps', pts: CA_CP, r: 7 }], time: 22 }, prog: 'forever{ if:L=1&&R=1{ stop:all } else{ if:L=1{ run:L,fwd,40 run:R,fwd,200 } else{ if:R=1{ run:L,fwd,200 run:R,fwd,40 } else{ run:all,fwd,200 } } } }' },
          x: "Aquest programa fa servir «per sempre»: a la ratlla diu «atura», però per la <b>inèrcia</b> el robot llisca un parell de centímetres i surt de la ratlla. A la volta següent de «per sempre», ja no veu la meta… i torna a arrencar!|Este programa usa «para siempre»: en la raya dice «para», pero por la <b>inercia</b> el robot se desliza un par de centímetros y sale de la raya. En la siguiente vuelta de «para siempre», ya no ve la meta… ¡y vuelve a arrancar!",
          bad: "«Per sempre» + «si ratlla, atura» deixa el robot quiet a la meta.|«Para siempre» + «si raya, para» deja el robot quieto en la meta.", good: "«Repeteix fins que L = 1 i R = 1» i després «atura»: un cop surt del bucle, ja no hi torna.|«Repite hasta que L = 1 y R = 1» y después «para»: una vez sale del bucle, ya no vuelve." },
        { k: 'Cronòmetre|Cronómetro', t: 'El temps al marcador|El tiempo en el marcador',
          robo: { w: { w: 140, h: 80, ...CA, goal: [{ k: 'cps', pts: CA_CP, r: 7 }], time: 20 }, prog: CURSA(200, 40, 200).replace('stop:all }', 'stop:all calc:s,t,/,1000 num:$s }'), varNames: { s: 'segons|segundos' } },
          x: "La micro:bit compta els mil·lisegons des que s'encén: és el valor <b>temps (ms)</b>. En arribar a la meta, «posa segons a temps ÷ 1000» i «mostra el número segons»: la pantalla ensenya els segons que ha tardat. Així pots comparar cada millora!|La micro:bit cuenta los milisegundos desde que se enciende: es el valor <b>tiempo (ms)</b>. Al llegar a la meta, «pon segundos a tiempo ÷ 1000» y «muestra el número segundos»: la pantalla enseña los segundos que ha tardado. ¡Así puedes comparar cada mejora!",
          tip: "Al robot de veritat és igual: input.runningTime() a MakeCode.|En el robot de verdad es igual: input.runningTime() en MakeCode." }
      ] },
      { k: 'seq', ph: 'mans', q: "Així treballa un equip de curses. Ordena el <b>cicle de millora</b>.|Así trabaja un equipo de carreras. Ordena el <b>ciclo de mejora</b>.",
        items: ['Planifica: quins sensors i quina velocitat faré servir?|Planifica: ¿qué sensores y qué velocidad usaré?', 'Programa la primera versió, segura i a poc a poc|Programa la primera versión, segura y despacio', 'Prova-la i mesura el temps|Pruébala y mide el tiempo', 'Canvia una sola cosa (per exemple, la velocitat)|Cambia una sola cosa (por ejemplo, la velocidad)', 'Torna a provar i compara: és més ràpid i encara funciona?|Vuelve a probar y compara: ¿es más rápido y todavía funciona?'],
        ex: "Si canvies moltes coses alhora, no sabràs quina ha millorat el temps (o quina l'ha espatllat).|Si cambias muchas cosas a la vez, no sabrás cuál ha mejorado el tiempo (o cuál lo ha estropeado)." },
      { k: 'unplug', ph: 'mans', ico: '✏️', title: 'El circuit de llapis|El circuito de lápiz',
        t: "Amb un full, un retolador gruixut, un llapis i un mòbil o rellotge per comptar segons. Dibuixa un circuit tancat amb dues corbes tancades i una de suau.|Con una hoja, un rotulador grueso, un lápiz y un móvil o reloj para contar segundos. Dibuja un circuito cerrado con dos curvas cerradas y una suave.",
        steps: ["Repassa el circuit amb el llapis <b>molt a poc a poc</b> mentre algú et cronometra. Apunta el temps i quantes vegades has sortit del retolador.|Repasa el circuito con el lápiz <b>muy despacio</b> mientras alguien te cronometra. Apunta el tiempo y cuántas veces te has salido del rotulador.",
          'Torna-ho a fer a velocitat normal i després <b>tan de pressa com puguis</b>.|Vuelve a hacerlo a velocidad normal y después <b>tan deprisa como puedas</b>.',
          "Fes una taula: velocitat, temps i sortides. Quina és la millor velocitat per a una cursa?|Haz una tabla: velocidad, tiempo y salidas. ¿Cuál es la mejor velocidad para una carrera?",
          "On t'has sortit més: a les rectes o a les corbes tancades?|¿Dónde te has salido más: en las rectas o en las curvas cerradas?"],
        tip: "Al teu robot li passa el mateix: a les corbes tancades cal més precisió.|A tu robot le pasa lo mismo: en las curvas cerradas hace falta más precisión." },
      { k: 'quiz', ph: 'prova', q: "Per què fem servir «repeteix fins que L = 1 i R = 1» en lloc de «per sempre»?|¿Por qué usamos «repite hasta que L = 1 y R = 1» en lugar de «para siempre»?",
        opts: ["Perquè, quan troba la ratlla, surt del bucle, s'atura i ja no torna a arrencar|Porque, cuando encuentra la raya, sale del bucle, se para y ya no vuelve a arrancar", 'Perquè així va més de pressa|Porque así va más deprisa', 'Perquè «per sempre» no pot seguir línies|Porque «para siempre» no puede seguir líneas'], a: 0 },
      { k: 'rspot', ph: 'investiga', q: "Aquest és el programa de la cursa. <b>Toca el bloc que atura el robot a la meta.</b>|Este es el programa de la carrera. <b>Toca el bloque que para el robot en la meta.</b>",
        w: { w: 140, h: 80, ...CA, goal: [{ k: 'cps', pts: CA_CP, r: 7 }], time: 18 }, scripts: ['start'],
        prog: CURSA(200, 40, 200).replace('stop:all }', 'stop:all! }'),
        yes: "Molt bé! Aquest «atura» va <b>després</b> del bucle: només s'executa quan el robot troba la ratlla.|¡Muy bien! Este «para» va <b>después</b> del bucle: solo se ejecuta cuando el robot encuentra la raya.",
        ex: "És l'«atura» del final, fora del «repeteix fins que»: quan L i R veuen negre alhora, el bucle s'acaba i el robot s'atura.|Es el «para» del final, fuera del «repite hasta que»: cuando L y R ven negro a la vez, el bucle termina y el robot se para." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Escalfament de pilot/a! Fes com si correguessis al lloc, a poc a poc (velocitat 100), després normal (150) i després molt de pressa (255) durant 5 segons. Ara inclina't a la dreta i a l'esquerra com si prenguessis corbes. I quan algú digui «meta!», atura't en sec… sense lliscar!|¡Calentamiento de piloto! Haz como si corrieras en el sitio, despacio (velocidad 100), después normal (150) y después muy deprisa (255) durante 5 segundos. Ahora inclínate a la derecha y a la izquierda como si tomaras curvas. Y cuando alguien diga «¡meta!», párate en seco… ¡sin deslizarte!" },
      { k: 'robo', ph: 'repte', q: "<b>Volta de reconeixement.</b> Aquest robot fa servir el seguiment del xip: va lent i no s'atura a la meta. Fes el teu propi seguidor que passi pels <b>5 punts de control</b> i s'<b>aturi a la meta</b>. Encara no hi ha límit de temps.|<b>Vuelta de reconocimiento.</b> Este robot usa el seguimiento del chip: va lento y no se para en la meta. Haz tu propio seguidor que pase por los <b>5 puntos de control</b> y se <b>pare en la meta</b>. Todavía no hay límite de tiempo.",
        w: { w: 140, h: 80, ...CA, goal: [{ k: 'cps', pts: CA_CP, r: 7 }, { k: 'zone', id: 'meta', stop: true }], time: 45 },
        pal: ['run', 'stop', 'wait', 'patrol', 'until', 'if', 'else', 'and'], ops: ['L', 'M', 'R'], scripts: ['start'],
        prog: 'start{ patrol:on }', sol: CURSA(150, 40, 150),
        hint: "Treu el seguiment del xip. Posa «repeteix fins que L = 1 i R = 1» i, a dins: si L = 1, gira a l'esquerra (esquerre a 40, dret a 150); si no, si R = 1, gira a la dreta; si no, endavant a 150. Després del bucle, «atura».|Quita el seguimiento del chip. Pon «repite hasta que L = 1 y R = 1» y, dentro: si L = 1, gira a la izquierda (izquierdo a 40, derecho a 150); si no, si R = 1, gira a la derecha; si no, adelante a 150. Después del bucle, «para»." },
      { k: 'robo', ph: 'repte', q: "<b>Contra el rellotge!</b> Ara la volta s'ha de fer en <b>menys de 18 segons</b>, i el mateix programa ha de funcionar al circuit del moll i al de la drassana, que té les corbes més tancades.|<b>¡Contra el reloj!</b> Ahora la vuelta se tiene que hacer en <b>menos de 18 segundos</b>, y el mismo programa tiene que funcionar en el circuito del muelle y en el del astillero, que tiene las curvas más cerradas.",
        w: { w: 140, h: 80, ...CA, goal: [{ k: 'cps', pts: CA_CP, r: 7 }, { k: 'zone', id: 'meta', stop: true }, { k: 'time', max: 18 }], time: 25,
          alts: [{ ...CB, goal: [{ k: 'cps', pts: CB_CP, r: 7 }, { k: 'zone', id: 'meta', stop: true }, { k: 'time', max: 18 }] }] },
        pal: ['run', 'stop', 'wait', 'until', 'if', 'else', 'and'], ops: ['L', 'M', 'R'], scripts: ['start'],
        prog: CURSA(150, 40, 150), sol: CURSA(200, 40, 200),
        hint: "A 150 tarda uns 21 segons. Puja la velocitat de les rectes i de la roda de fora dels girs (prova amb 200). Canvia una cosa cada vegada i mira el temps!|A 150 tarda unos 21 segundos. Sube la velocidad de las rectas y de la rueda de fuera de los giros (prueba con 200). ¡Cambia una cosa cada vez y mira el tiempo!" },
      { k: 'robo', ph: 'repte', q: "<b>Bat el rècord!</b> El rècord del circuit del moll és de <b>13 segons</b>. Ho aconsegueixes sense sortir de la línia?|<b>¡Bate el récord!</b> El récord del circuito del muelle es de <b>13 segundos</b>. ¿Lo consigues sin salirte de la línea?",
        w: { w: 140, h: 80, ...CA, goal: [{ k: 'cps', pts: CA_CP, r: 7 }, { k: 'zone', id: 'meta', stop: true }, { k: 'time', max: 13 }], time: 20 },
        pal: ['run', 'stop', 'wait', 'until', 'if', 'else', 'and'], ops: ['L', 'M', 'R'], scripts: ['start'],
        prog: CURSA(200, 40, 200), sol: CURSA(255, 60, 255),
        hint: "Has d'anar a la velocitat màxima, 255. Però si la roda de dins dels girs va massa lenta, el robot fa esses: prova de posar-la a 60.|Tienes que ir a la velocidad máxima, 255. Pero si la rueda de dentro de los giros va demasiado lenta, el robot hace eses: prueba a ponerla a 60." },
      { k: 'story', ph: 'crea', who: 'numi', title: 'El teu projecte|Tu proyecto',
        t: "Ara, el gran circuit del port! Té dues corbes grans i una <b>xicana</b> (unes esses) a la recta de baix. Abans de programar, fes el teu pla:|¡Ahora, el gran circuito del puerto! Tiene dos curvas grandes y una <b>chicane</b> (unas eses) en la recta de abajo. Antes de programar, haz tu plan:",
        box: "<ul><li><b>Sensors</b>: L i R per seguir la línia i per trobar la ratlla de meta.</li><li><b>Velocitat</b>: comença segur (200) i puja a poc a poc.</li><li><b>Meta</b>: «repeteix fins que L = 1 i R = 1» i «atura».</li><li><b>Marcador</b>: mostra els segons a la pantalla.</li><li><b>Prova i millora</b>: apunta el temps de cada versió.</li></ul>|<ul><li><b>Sensores</b>: L y R para seguir la línea y para encontrar la raya de meta.</li><li><b>Velocidad</b>: empieza seguro (200) y sube poco a poco.</li><li><b>Meta</b>: «repite hasta que L = 1 y R = 1» y «para».</li><li><b>Marcador</b>: muestra los segundos en la pantalla.</li><li><b>Prueba y mejora</b>: apunta el tiempo de cada versión.</li></ul>" },
      { k: 'rcreate', ph: 'crea', name: 'La cursa contrarellotge del port|La carrera contrarreloj del puerto',
        q: "<b>El teu projecte!</b> Programa el robot per a la cursa del port: una volta passant pels 5 punts de control, aturat a la meta en <b>menys de 20 segons</b> i, en arribar, que <b>mostri el temps</b> a la pantalla. Després, intenta baixar el teu propi rècord!|<b>¡Tu proyecto!</b> Programa el robot para la carrera del puerto: una vuelta pasando por los 5 puntos de control, parado en la meta en <b>menos de 20 segundos</b> y, al llegar, que <b>muestre el tiempo</b> en la pantalla. Después, ¡intenta bajar tu propio récord!",
        crit: ['Passa pels 5 punts de control en ordre|Pasa por los 5 puntos de control en orden', "S'atura a la meta en menys de 20 segons|Se para en la meta en menos de 20 segundos", 'Mostra el temps a la pantalla en arribar|Muestra el tiempo en la pantalla al llegar'],
        w: { w: 150, h: 84, ...CP_PORT, goal: [{ k: 'cps', pts: PORT_CP, r: 7 }, { k: 'zone', id: 'meta', stop: true }, { k: 'time', max: 20 }], time: 28 },
        pal: ['run', 'stop', 'wait', 'until', 'if', 'else', 'and', 'calc', 'num', 'car', 'icon', 'note'], ops: ['L', 'M', 'R', 'time'], scripts: ['start'], vars: ['s'], varNames: { s: 'segons|segundos' },
        sol: CURSA(200, 40, 200).replace('stop:all }', 'stop:all car:all,green calc:s,t,/,1000 num:$s }'),
        check(P) { return has(P, 'num') ? null : "Volta feta! Ara falta el marcador: en arribar, mostra el número del temps (temps ÷ 1000 són els segons).|¡Vuelta hecha! Ahora falta el marcador: al llegar, muestra el número del tiempo (tiempo ÷ 1000 son los segundos)."; } },
      { k: 'quiz', ph: 'tanca', q: "El teu robot fa la volta en 16 segons a velocitat 200. A 255 fa esses i es confon a la xicana. Què fa un bon equip de curses?|Tu robot da la vuelta en 16 segundos a velocidad 200. A 255 hace eses y se confunde en la chicane. ¿Qué hace un buen equipo de carreras?",
        opts: ['Prova velocitats entremig (210, 220…) i es queda amb la més ràpida que sempre funciona|Prueba velocidades intermedias (210, 220…) y se queda con la más rápida que siempre funciona', 'Posa sempre 255, encara que falli|Pone siempre 255, aunque falle', 'Torna al seguiment del xip|Vuelve al seguimiento del chip'], a: 0 },
      { k: 'story', ph: 'tanca', who: 'both', mood: 'win',
        t: "Setmana de les Missions superada! El teu robot ha netejat l'hostal, ha guanyat al dohyo, ha rescatat les balises de la cova i ha corregut contra el rellotge. A la propera unitat faràs el pas definitiu: <b>dissenyaràs la teva pròpia missió</b> i la provaràs al Maqueen de veritat.|¡Semana de las Misiones superada! Tu robot ha limpiado el hostal, ha ganado en el dohyo, ha rescatado las balizas de la cueva y ha corrido contra el reloj. En la próxima unidad darás el paso definitivo: <b>diseñarás tu propia misión</b> y la probarás en el Maqueen de verdad." },
      { k: 'feel', ph: 'tanca' }
    ] }
  ] };
})();
